/**
 * Cross-language check: the TypeScript pricing port must produce byte-identical
 * results to the Rust engine (spec §6, §12.29 — "quoted total in the buy panel
 * equals lamports actually debited").
 *
 * Vectors are generated by `cargo test -p rigs-engine --test vectors`.
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

import { MAX_RIGS_PER_PURCHASE } from '../src/lib/program/constants';
import { quotePurchase, rigsAffordable } from '../src/lib/program/pricing';

const raw = readFileSync(
  join(import.meta.dirname, 'fixtures', 'pricing-vectors.txt'),
  'utf8',
);

/** Parsed fixture rows, so index access below is total rather than partial. */
function section(name: string): bigint[][] {
  const lines = raw.split('\n');
  const start = lines.indexOf(`---${name}---`);
  expect(start, `section ${name} missing from fixture`).toBeGreaterThanOrEqual(0);
  const out: bigint[][] = [];
  for (let i = start + 1; i < lines.length; i++) {
    const l = (lines[i] ?? '').trim();
    if (l.startsWith('---')) break;
    if (l) out.push(l.split(',').map((v) => BigInt(v)));
  }
  return out;
}

/** Destructure a fixture row, asserting its arity. */
function cols<N extends number>(row: bigint[], n: N): bigint[] {
  expect(row.length, `expected ${n} columns in ${row.join(',')}`).toBe(n);
  return row;
}

describe('quotePurchase matches the Rust engine', () => {
  const rows = section('QUOTES');

  it('has a non-trivial number of vectors', () => {
    expect(rows.length).toBeGreaterThan(300);
  });

  it('agrees on every vector', () => {
    for (const row of rows) {
      const [count, price, bps, capital, fee, total] = cols(row, 6) as [
        bigint, bigint, bigint, bigint, bigint, bigint,
      ];
      const q = quotePurchase(count, price, bps);
      expect(
        [q.capitalLamports, q.feeLamports, q.totalLamports],
        `count=${count} price=${price} bps=${bps}`,
      ).toEqual([capital, fee, total]);
      // The displayed breakdown must always add up.
      expect(q.capitalLamports + q.feeLamports).toBe(q.totalLamports);
    }
  });
});

describe('rigsAffordable matches the Rust engine', () => {
  const rows = section('AFFORDABLE');

  it('agrees on every vector', () => {
    for (const row of rows) {
      const [budget, price, bps, expected] = cols(row, 4) as [
        bigint, bigint, bigint, bigint,
      ];
      expect(
        rigsAffordable(budget, price, bps),
        `budget=${budget} price=${price} bps=${bps}`,
      ).toBe(expected);
    }
  });

  it('never returns a count the budget cannot pay for', () => {
    for (const row of rows) {
      const [budget, price, bps] = cols(row, 4) as [bigint, bigint, bigint, bigint];
      const n = rigsAffordable(budget, price, bps);
      if (n > 0n) {
        expect(quotePurchase(n, price, bps).totalLamports).toBeLessThanOrEqual(budget);
      }
      // `n` is clamped at MAX_RIGS_PER_PURCHASE, where "one more" is not a
      // valid quote at all — the cap, not the budget, is the binding limit.
      if (n < MAX_RIGS_PER_PURCHASE) {
        expect(quotePurchase(n + 1n, price, bps).totalLamports).toBeGreaterThan(budget);
      }
    }
  });
});

describe('the spec worked example', () => {
  it('turns 0.128 SOL into 12 rigs with 0.008 SOL left over', () => {
    const price = 10_000_000n; // 0.01 SOL
    const n = rigsAffordable(128_000_000n, price, 0n);
    expect(n).toBe(12n);
    const q = quotePurchase(n, price, 0n);
    expect(q.totalLamports).toBe(120_000_000n);
    expect(128_000_000n - q.totalLamports).toBe(8_000_000n);
  });

  it('quotes the buy panel exactly as the spec screen shows it', () => {
    // COST 0.100 / FEE 0.003 / TOTAL 0.103 at 10 rigs, 0.01 SOL, 3.00%.
    const q = quotePurchase(10n, 10_000_000n, 300n);
    expect(q.capitalLamports).toBe(100_000_000n);
    expect(q.feeLamports).toBe(3_000_000n);
    expect(q.totalLamports).toBe(103_000_000n);
  });
});

describe('guardrails', () => {
  it('rejects a zero rig price', () => {
    expect(() => quotePurchase(1n, 0n, 0n)).toThrow();
  });
  it('rejects a zero or oversized count', () => {
    expect(() => quotePurchase(0n, 1n, 0n)).toThrow();
    expect(() => quotePurchase(1_000_001n, 1n, 0n)).toThrow();
  });
  it('returns zero affordable rigs for an empty budget', () => {
    expect(rigsAffordable(0n, 10_000_000n, 300n)).toBe(0n);
  });
});
